    (5,2,0,'mtext','write','{"k": "mtext", "tag": "write", "title": "At the Shop", "text": ["May I help you?", "Yes, please. How much are [[these shoes]]?", "They''re [[thirty thousand]] won."], "explain": ["가게 주인이 도움을 제안합니다.", "{{물건}}의 가격을 물어봅니다.", "{{가격}}을 말해 줍니다."], "ko": "도와드릴까요?\n네, 부탁해요. 이 신발은 얼마예요?\n30,000원이에요."}'),
    (5,3,0,'mwbank','write','{"k": "mwbank", "tag": "write", "lines": ["A: May I help you?", "B: Yes, please. How much are {}?", "A: {} thirty thousand won."], "ans": ["these shoes", "They''re"], "extra": ["this shoes"], "blankHints": ["신발이 여러 개예요. these 와 함께 써요.", "these shoes 를 받는 말이에요. They''re 인가요, It''s 인가요?"]}'),
    (5,3,1,'mwbank','write','{"k": "mwbank", "tag": "write", "lines": ["A: How much are {} socks?", "B: {} two thousand won."], "ans": ["these", "They''re"], "extra": ["this"], "blankHints": ["양말은 한 켤레가 아니라 여러 개로 말해요.", "가격을 말하는 첫 말이에요."]}'),
    (5,4,0,'mfree','write','{"k": "mfree", "tag": "write", "lines": ["How much are {}?", "They''re {} won."], "lineHints": ["이 물건의 가격을 물어요. (예: these socks, these hats)", "가격을 말해요. (예: two thousand)"], "hint": ["How much are these hats?"]}'),
