    (6,0,0,'lchpic','listen','{"k": "lchpic", "tag": "listen", "q": "가격을 물은 물건은 무엇일까요?", "say": "May I help you? Yes, please. How much are these shoes?", "opts": [{"t": "hat", "flag": "hat"}, {"t": "sunglasses", "flag": "sunglasses"}, {"t": "shoes", "flag": "shoes"}, {"t": "jacket", "flag": "jacket"}], "a": 2, "hint": ["May I help you? Yes, please. How much are these shoes?"]}'),
    (6,0,1,'lchpic','listen','{"k": "lchpic", "tag": "listen", "q": "가격을 물은 물건은 무엇일까요?", "say": "How much are these sunglasses? They''re thirteen thousand won.", "opts": [{"t": "hat", "flag": "hat"}, {"t": "jacket", "flag": "jacket"}, {"t": "sunglasses", "flag": "sunglasses"}, {"t": "shorts", "flag": "shorts"}], "a": 2, "hint": ["How much are these sunglasses? They''re thirteen thousand won."]}'),
    (6,1,0,'sqchoice','read','{"k": "sqchoice", "tag": "read", "pic": "hat", "title": "Class Bazaar Day", "text": ["Today is Class Bazaar Day. Mina has a shop.", "She has socks, shoes, and hats.", "Ken comes to her shop. Mina says, \"May I help you?\"", "Ken says, \"Yes, please. How much are these socks?\"", "---", "Mina says, \"They''re two thousand won.\"", "Ken says, \"How much are these hats?\"", "\"They''re ten thousand won.\""], "ko": "오늘은 학급 바자회 날이야. 미나는 가게가 있어.\n미나는 양말, 신발, 모자가 있어.\n켄이 가게에 와. 미나가 \"도와드릴까요?\"라고 말해.\n켄이 \"네, 부탁해요. 이 양말은 얼마예요?\"라고 말해.\n---\n미나가 \"2,000원이에요.\"라고 말해.\n켄이 \"이 모자는 얼마예요?\"라고 물어.\n\"10,000원이에요.\"", "q": "How much are the hats?", "opts": [{"t": "2,000 won"}, {"t": "10,000 won"}, {"t": "13,000 won"}, {"t": "30,000 won"}], "a": 1, "hint": ["\"They''re ten thousand won.\""]}'),
    (6,1,1,'sqchoice','read','{"k": "sqchoice", "tag": "read", "pic": "shorts", "title": "At the Shop", "text": ["Sora is at a clothes shop.", "She wants new shorts and sunglasses.", "She asks, \"How much are these shorts?\"", "The clerk says, \"They''re fifteen thousand won.\"", "---", "Sora says, \"How much are these sunglasses?\"", "\"They''re thirteen thousand won.\"", "Sora says, \"Thank you!\""], "ko": "소라는 옷 가게에 있어.\n소라는 새 반바지와 선글라스를 원해.\n소라가 \"이 반바지는 얼마예요?\"라고 물어.\n점원이 \"15,000원이에요.\"라고 말해.\n---\n소라가 \"이 선글라스는 얼마예요?\"라고 물어.\n\"13,000원이에요.\"\n소라가 \"고마워요!\"라고 말해.", "q": "How much are the shorts?", "opts": [{"t": "13,000 won"}, {"t": "50,000 won"}, {"t": "5,000 won"}, {"t": "15,000 won"}], "a": 3, "hint": ["\"They''re fifteen thousand won.\""]}'),
    (6,2,0,'role','speak','{"k": "role", "tag": "speak", "pic": "jacket", "lines": ["A: May I help you?", "B: Yes, please. How much are {{these jackets}}?", "A: [[They''re fifty thousand]] won."]}'),
    (6,3,0,'aitalk','speak','{"k": "aitalk", "tag": "speak", "situation": "You are at a clothes shop. You want to buy shorts.", "role": "a clothes shop clerk", "open": "Hello! May I help you?", "script": [{"ai": "Sure! What do you want?", "hint": "Yes, please. 이라고 말해 보세요"}, {"ai": "These shorts? They''re fifteen thousand won.", "hint": "How much are these shorts? 라고 물어보세요"}], "turns": 2}'),
    (6,4,0,'sbuild','write','{"k": "sbuild", "tag": "write", "ko": "이 신발은 얼마예요?", "ans": "How much are these shoes?"}'),
    (6,4,1,'sbuild','write','{"k": "sbuild", "tag": "write", "ko": "30,000원이에요.", "ans": "They''re thirty thousand won."}')
  ) as x(l,p,o,k,tag,pl)
  join flow_lessons fl on fl.unit_id=u9 and fl.no=x.l
